python3 - <<'PY'
import ast, pathlib
from collections import defaultdict
src = pathlib.Path('src/browser_tools')
tools = set()
tr = (src/'tool_registry.py').read_text()
import re
tools = set(re.findall(r'^\s*"([a-z_]+)": ToolFlags', tr, re.M))
print("tool names:", len(tools))
hits = defaultdict(list)
for f in sorted(src.glob('*.py')):
    tree = ast.parse(f.read_text())
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and getattr(node.func, 'id', '') in ('make_error',):
            parts=[]
            for a in node.args:
                for sub in ast.walk(a):
                    if isinstance(sub, ast.Constant) and isinstance(sub.value, str):
                        parts.append(sub.value)
            msg = ' '.join(parts)
            for t in tools:
                if re.search(rf'\b{re.escape(t)}\b', msg):
                    hits[f.name].append((node.lineno, t, msg[:110]))
for fn, rows in hits.items():
    for ln, t, msg in rows:
        print(f"{fn}:{ln}  tool={t}\n    {msg}")
if not hits: print("no make_error message names an internal tool")
PY

