/** Deploy generated flat copies. The historical entrypoint remains `link.ts`. */
import { mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deploySkills } from "./deploy-skills.ts";

function main(): void {
  const userHome = homedir();
  const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
  const roots: string[] = [];
  const targets: string[] = [];
  let dryRun = false;
  let json = false;
  let map = join(repoRoot, ".generated/skill-map.json");
  const args = process.argv.slice(2);
  for (let index = 0; index < args.length; index++) {
    const arg = args[index];
    if (arg === "--dry-run") dryRun = true;
    else if (arg === "--json") json = true;
    else if (arg === "--source" || arg === "--target" || arg === "--map") {
      const value = args[++index];
      if (!value || value.startsWith("--")) throw new Error(`${arg} needs a path`);
      if (arg === "--source") roots.push(value);
      else if (arg === "--target") targets.push(value);
      else map = resolve(value);
    } else if (arg === "--help") {
      console.log("Usage: link.ts [--dry-run] [--json] [--source <root>]... [--target <root>]... [--map <file>]\nDeploys flat skill copies with rewritten Markdown links to the first physical target. Other roots receive per-skill aliases to that flat store; whole-root aliases are also supported. Defaults merge this library, the legacy dotfiles root, and the lucid project root, targeting shared and Claude skill roots. Explicit sources/targets replace their defaults. Writes .generated/skill-map.json after deployment; dry-run writes nothing.");
      return;
    } else throw new Error(`Unknown argument: ${arg}`);
  }
  const result = deploySkills({
    dryRun,
    roots: roots.length ? roots : [join(repoRoot, "skills"), join(userHome, "dev/dotfiles/agents/.agents/skills"), join(userHome, "dev/lucid/skills")],
    targets: targets.length ? targets : [join(userHome, ".agents/skills"), join(userHome, ".claude/skills"), join(userHome, "dev/dotfiles/codex/.codex/skills")],
  });
  if (!dryRun) { mkdirSync(dirname(map), { recursive: true }); writeFileSync(map, `${JSON.stringify(result.graph, null, 2)}\n`); }
  if (json) console.log(JSON.stringify(result, null, 2));
  else {
    for (const warning of [...result.graph.warnings, ...result.warnings]) console.warn(`warn: ${warning}`);
    for (const action of result.actions) console.log(`${dryRun ? "would " : ""}${action}`);
    console.log(`${result.graph.nodes.length} skills; ${result.actions.length} changes${dryRun ? " (dry run)" : `; map: ${map}`}`);
  }
}

