python3 - <<'PY'
import re, pathlib
def sections(p):
    t = pathlib.Path(p).read_text()
    out, cur, buf = {}, None, []
    for line in t.splitlines():
        if line.startswith("### "):
            if cur: out[cur] = "\n".join(buf).strip()
            cur, buf = line[4:], []
        else: buf.append(line)
    if cur: out[cur] = "\n".join(buf).strip()
    return out
a, b = sections("/tmp/nine/main.txt"), sections("/tmp/nine/branch2.txt")
same = diff = 0
for k in a:
    x, y = a[k], b.get(k, "<MISSING>")
    # traceback bodies and per-run ids are expected to differ
    if "Traceback" in x or "Traceback" in y:
        # compare only the final exception line
        fx = [l for l in x.splitlines() if "Error:" in l or l.startswith("exit=")]
        fy = [l for l in y.splitlines() if "Error:" in l or l.startswith("exit=")]
        ok = fx == fy
    else:
        norm = lambda s: re.sub(r"\d+", "#", s)
        ok = norm(x) == norm(y)
    print(("SAME  " if ok else "DIFF  ") + k)
    same, diff = same + ok, diff + (not ok)
print(f"\n{same} sections identical, {diff} different")
PY

