        fy = [l for l in y.splitlines() if "Error:" in l or l.startswith("exit=")]
        ok = fx == fy
    else:
        norm = lambda s: re.sub(r"\d+", "#", s)
        ok = norm(x) == norm(y)
    print(("SAME  " if ok else "DIFF  ") + k)
    same, diff = same + ok, diff + (not ok)
print(f"\n{same} sections identical, {diff} different")
